import json
import time
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from urllib.error import HTTPError
from urllib.request import Request, urlopen


class MeridianClient:
    def __init__(self, base_url: str, api_key: str) -> None:
        self._base_url = base_url.rstrip("/")
        self._api_key = api_key
        self._etag: str | None = None
        self._cached_payments: list[dict] | None = None

    def _handle_retry_after(self, resp: HTTPError) -> None:
        header = resp.headers.get("Retry-After")
        if header is None:
            return
        try:
            seconds = int(header)
        except ValueError:
            dt = parsedate_to_datetime(header)
            seconds = max(0, int((dt.timestamp() - time.time())))
        time.sleep(seconds)

    def _request(self, url: str, method: str = "GET", data: bytes | None = None, extra_headers: dict | None = None) -> tuple[bytes, dict]:
        headers = {
            "Authorization": f"Bearer {self._api_key}",
        }
        if extra_headers:
            headers.update(extra_headers)

        req = Request(url, method=method, data=data, headers=headers)
        try:
            resp = urlopen(req)
            body = resp.read()
            resp_headers = dict(resp.headers)
            return body, resp_headers
        except HTTPError as e:
            if e.code == 429:
                self._handle_retry_after(e)
                return self._request(url, method, data, extra_headers)
            raise

    def fetch_all_payments(self) -> list[dict]:
        cursor = None
        all_payments: list[dict] = []

        while True:
            params = f"?limit=100"
            if cursor is not None:
                params += f"&cursor={cursor}"
            url = f"{self._base_url}/v1/payments{params}"

            extra_headers = {}
            first_page = (cursor is None)
            if first_page and self._etag is not None:
                extra_headers["If-None-Match"] = self._etag

            try:
                body, resp_headers = self._request(url, "GET", extra_headers=extra_headers)
            except HTTPError as e:
                if e.code == 304 and first_page and self._cached_payments is not None:
                    return self._cached_payments
                raise

            # Update etag from response headers
            new_etag = resp_headers.get("ETag") or resp_headers.get("etag")
            if new_etag is not None:
                self._etag = new_etag

            try:
                resp_json = json.loads(body)
            except json.JSONDecodeError as exc:
                raise ValueError(f"Invalid JSON from Meridian API: {body!r}") from exc

            if first_page and "cursor_expired" in (resp_json.get("error") or ""):
                # Treat cursor_expired on first page like 410 — restart (already at start)
                pass

            data = resp_json.get("data", [])
            all_payments.extend(data)
            next_cursor = resp_json.get("next_cursor")
            if next_cursor is None:
                break
            cursor = next_cursor

        # Sort ascending by UTC instant
        def utc_key(p: dict) -> datetime:
            return datetime.fromisoformat(p["created_at"]).astimezone(timezone.utc)

        all_payments.sort(key=utc_key)
        self._cached_payments = all_payments
        return all_payments

    def total_count(self) -> int:
        url = f"{self._base_url}/v1/payments?limit=1"
        body, _ = self._request(url, "GET")
        resp_json = json.loads(body)
        return resp_json.get("total", 0)

    def create_payment(self, amount_minor: int, currency: str, idempotency_key: str) -> str:
        url = f"{self._base_url}/v1/payments"
        payload = json.dumps({"amount_minor": amount_minor, "currency": currency}).encode("utf-8")
        extra_headers = {
            "Idempotency-Key": idempotency_key,
            "Content-Type": "application/json",
        }

        try:
            body, _ = self._request(url, "POST", data=payload, extra_headers=extra_headers)
        except HTTPError as e:
            if e.code == 409:
                resp_json = json.loads(e.read())
                if resp_json.get("error") == "duplicate":
                    return resp_json["payment_id"]
            raise

        resp_json = json.loads(body)
        return resp_json["id"]

