class MockResponse:
    """Minimal HTTPResponse-like object for mocking urlopen."""

    def __init__(self, body: bytes, headers: dict | None = None, status: int = 200):
        self._body = body
        self._headers = EmailMessage()
        if headers:
            for k, v in headers.items():
                self._headers[k] = str(v)
        self.status = status

    def read(self) -> bytes:
        return self._body

    @property
    def headers(self):
        return self._headers

    def getheader(self, name, default=None):
        return self._headers.get(name, default)


def make_error_response(code: int, body: dict | None = None, headers: dict | None = None, url: str = "http://example.com") -> HTTPError:
    """Create an HTTPError for mocking."""
    if headers is None:
        headers = {}
    msg_headers = EmailMessage()
    for k, v in headers.items():
        msg_headers[k] = str(v)
    body_bytes = json.dumps(body).encode("utf-8") if body else b""
    return HTTPError(url, code, "Error", msg_headers, BytesIO(body_bytes))


class TestHappyPathPagination(unittest.TestCase):
    def test_pagination_across_three_pages(self):
        page_calls = []

        def mock_urlopen(req: Request):
            url = req.full_url
            page_calls.append(url)

            if "?limit=100" in url and "cursor" not in url:
                # Page 1
                data = [
                    {"id": "p1", "amount_minor": 100, "currency": "USD",
                     "created_at": "2026-01-01T10:00:00Z", "status": "succeeded"},
                ]
                return MockResponse(
                    json.dumps({"data": data, "next_cursor": "c1"}).encode(),
                    {"ETag": '"v1"'}
                )
            elif "cursor=c1" in url:
                # Page 2
                data = [
                    {"id": "p2", "amount_minor": 200, "currency": "USD",
                     "created_at": "2026-01-02T10:00:00Z", "status": "succeeded"},
                ]
                return MockResponse(
                    json.dumps({"data": data, "next_cursor": "c2"}).encode(),
                )
            elif "cursor=c2" in url:
                # Page 3 (last)
                data = [
                    {"id": "p3", "amount_minor": 300, "currency": "USD",
                     "created_at": "2026-01-03T10:00:00Z", "status": "succeeded"},
                ]
                return MockResponse(
                    json.dumps({"data": data, "next_cursor": None}).encode(),
                )
            raise ValueError(f"Unexpected URL: {url}")

        client = MeridianClient("http://127.0.0.1:8930", "sk_test_meridian")

        with patch("vendorsync.meridian.urlopen", mock_urlopen):
            result = client.fetch_all_payments()

        self.assertEqual(len(result), 3)
        ids = [p["id"] for p in result]
        self.assertEqual(ids, ["p1", "p2", "p3"])

        # Verify Authorization header was sent
        self.assertTrue(all("Authorization" in dict(req.headers) for req in page_calls))


