class TestUtcSorting(unittest.TestCase):
    def test_mixed_offset_timestamps_sorted_by_utc(self):
        """Payments are out-of-order lexicographically but must be sorted by UTC instant."""
        def mock_urlopen(req: Request):
            # Order: +02:00 (earliest UTC), then -05:00, then Z — lexicographic != UTC order
            data = [
                {"id": "p_paris", "amount_minor": 100, "currency": "EUR",
                 "created_at": "2026-01-01T12:00:00+02:00", "status": "succeeded"},  # 10:00 UTC
                {"id": "p_ny", "amount_minor": 200, "currency": "USD",
                 "created_at": "2026-01-01T15:00:00-05:00", "status": "succeeded"},  # 20:00 UTC
                {"id": "p_utc", "amount_minor": 300, "currency": "USD",
                 "created_at": "2026-01-01T14:00:00Z", "status": "succeeded"},      # 14:00 UTC
            ]
            return MockResponse(
                json.dumps({"data": data, "next_cursor": None}).encode(),
            )

        client = MeridianClient("http://127.0.0.1:8930", "sk_test_meridian")

        with patch("vendorsync.meridian.urlopen", mock_urlopen):
            result = client.fetch_all_payments()

        ids = [p["id"] for p in result]
        # UTC ascending: p_paris (10:00), p_utc (14:00), p_ny (20:00)
        self.assertEqual(ids, ["p_paris", "p_utc", "p_ny"])


class TestRetryAfterSeconds(unittest.TestCase):
    def test_429_retry_after_integer_seconds(self):
        call_count = [0]

        def mock_urlopen(req: Request):
            call_count[0] += 1
            if call_count[0] == 1:
                # First attempt: rate limited
                raise make_error_response(
                    429, None, {"Retry-After": "1"}, req.full_url
                )
            # Retry succeeds with data
            data = [{"id": "p1", "amount_minor": 100, "currency": "USD",
                     "created_at": "2026-01-01T10:00:00Z", "status": "succeeded"}]
            return MockResponse(
                json.dumps({"data": data, "next_cursor": None}).encode(),
            )

