                return MockResponse(
                    json.dumps({"data": data, "next_cursor": "c1"}).encode(),
                )
            # First run, page 2 → cursor expired (410)
            if call_count[0] == 2 and "cursor=c1" in url:
                raise make_error_response(
                    410, {"error": "cursor_expired"}, {}, req.full_url
                )
            # Restart, page 1 (after dedup, client should collect all)
            if call_count[0] == 3 and "cursor" not in url:
                data = [
                    {"id": "p1", "amount_minor": 100, "currency": "USD",
                     "created_at": "2026-01-01T10:00:00Z", "status": "succeeded"},
                    {"id": "p2", "amount_minor": 200, "currency": "USD",
                     "created_at": "2026-01-02T10:00:00Z", "status": "succeeded"},
                ]
                return MockResponse(
                    json.dumps({"data": data, "next_cursor": "c2"}).encode(),
                )
            # Restart, page 2 (last)
            if call_count[0] == 4 and "cursor=c2" in url:
                data = [{"id": "p3", "amount_minor": 300, "currency": "USD",
