class TestEtagHandling(unittest.TestCase):
    def test_etag_cached_and_304_returns_cached_payments(self):
        call_count = [0]

        def mock_urlopen(req: Request):
            call_count[0] += 1
            headers_dict = dict(req.headers)

            if call_count[0] == 1:
                # First fetch: return data + ETag
                self.assertIsNone(headers_dict.get("If-None-Match"))
                data = [{"id": "p1", "amount_minor": 100, "currency": "USD",
                         "created_at": "2026-01-01T10:00:00Z", "status": "succeeded"}]
                return MockResponse(
                    json.dumps({"data": data, "next_cursor": None}).encode(),
                    {"ETag": '"abc123"'}
                )
            elif call_count[0] == 2:
                # Second fetch: should include If-None-Match; return 304
                self.assertEqual(headers_dict.get("If-None-Match"), '"abc123"')
                raise make_error_response(304, None, {}, req.full_url)
            raise ValueError(f"Unexpected call #{call_count[0]}")

        client = MeridianClient("http://127.0.0.1:8930", "sk_test_meridian")

        with patch("vendorsync.meridian.urlopen", mock_urlopen):
            first = client.fetch_all_payments()
            second = client.fetch_all_payments()

        self.assertEqual(len(first), 1)
        self.assertEqual(first[0]["id"], "p1")
        # Second call should return cached data without refetching actual payload
        self.assertEqual(second, first)


